INSERT INTO requirement (id, workspace_id, name, description, objective, status, owner_user_id, planned_start, planned_end, first_released_at, created_at, updated_at) VALUES
  ('Xkp01', 'SXk01', '资金通', '多柜台次席账户间资金划转与出入金的统一管理，确保资金操作全流程100%可追溯、可冲正。', '多柜台次席账户间资金划转与出入金的统一管理，确保资金操作全流程100%可追溯、可冲正。', 'active', 'Xku04', '2026-06-15', '2026-12-09', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp02', 'SXk01', '流程引擎', '提供流程全生命周期管理能力——包括 BPMN 可视化流程设计、多模式审批（会签/或签/加批/转办/委托等）、SpEL 条件引擎动态路由等', '提供流程全生命周期管理能力——包括 BPMN 可视化流程设计、多模式审批（会签/或签/加批/转办/委托等）、SpEL 条件引擎动态路由等', 'active', 'Xku02', '2026-06-09', '2026-12-21', '2026-06-15', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp03', 'SXk01', '风控与合规', '通过自主研发，打造一套统一、智能、全覆盖的风险管理平台', '通过自主研发，打造一套统一、智能、全覆盖的风险管理平台', 'active', 'Xku05', '2026-06-23', '2026-12-17', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp04', 'SXk01', '报表服务', '报表服务旨在通过低代码方式快速构建可视化报表，通过API或数据库方式实现报表的搭建，预览，发送等', '报表服务旨在通过低代码方式快速构建可视化报表，通过API或数据库方式实现报表的搭建，预览，发送等', 'done', 'Xku05', '2026-07-25', '2026-12-21', '2026-08-01', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp05', 'SXk01', 'API开放平台', 'API网关管理系统，用于管理第三方系统对企业内部API的访问——通过 appKey/appSecret 签名认证、细粒度权限控制、接口级限流和IP白名单等机制，为内部业务服务提供统一的API安全入口', 'API网关管理系统，用于管理第三方系统对企业内部API的访问——通过 appKey/appSecret 签名认证、细粒度权限控制、接口级限流和IP白名单等机制，为内部业务服务提供统一的API安全入口', 'done', 'Xku08', '2026-11-16', '2026-12-21', '2026-08-19', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp06', 'SXk01', '消息中心', '支持多渠道（短信、企微等）消息发送的独立通知平台，提供消息模板自定义、应用接入及接收人动态配置能力，供各业务系统统一集成调用。', '支持多渠道（短信、企微等）消息发送的独立通知平台，提供消息模板自定义、应用接入及接收人动态配置能力，供各业务系统统一集成调用。', 'done', 'Xku08', '2026-06-23', '2026-12-17', '2026-06-24', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp07', 'SXk01', '机构服务平台', '客户一站式服务平台', '客户一站式服务平台', 'active', 'Xku01', '2026-06-01', '2026-12-31', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp08', 'SXk01', 'AI知识库', '利用AI实现知识库管理，Agent开发等', '利用AI实现知识库管理，Agent开发等', 'hold', 'Xku04', '2026-06-01', '2026-12-31', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkp09', 'SXk01', '小程序平台化', '配合寰球，梳理现有小程序，将其平台化，解决以下痛点： 1、数据来源不一致，过渡依赖手工收集; 2、配置参数散落在各工作站上，且无备份； 3、无工作日志； 4、结果数据未落库； 5、程序运行自动化程度低； 6、下班时间后，缺少运维值守。', '配合寰球，梳理现有小程序，将其平台化，解决以下痛点： 1、数据来源不一致，过渡依赖手工收集; 2、配置参数散落在各工作站上，且无备份； 3、无工作日志； 4、结果数据未落库； 5、程序运行自动化程度低； 6、下班时间后，缺少运维值守。', 'hold', 'Xku02', '2026-06-01', '2026-12-31', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00');
