  ('Xkdf0005', 'SXk01', 'Xkp02', NULL, '外接模块', 'other', '<p>外接模块相关需求文档，共 2 篇。</p>', 'html', '外接模块（2 篇文档）', 'active', NULL, 0, '施亚彬', 'Xku02', '2026-06-01 09:00:00', '2026-06-01 09:00:00'),
