INSERT INTO project_version (id, workspace_id, req_id, name, description, status, start_date, target_date, released_at, created_at, updated_at) VALUES
  ('Xkv01', 'SXk01', 'Xkp02', 'V0.8', '软件台账写入,程序化报备录入成功消息发送,软件台账写入,外接台账新增时间筛选', 'released', '2026-05-16', '2026-06-15', '2026-06-15 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv02', 'SXk01', 'Xkp02', 'V0.81', '外接软件台账支持编辑和查询', 'released', '2026-05-17', '2026-06-16', '2026-06-16 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv03', 'SXk01', 'Xkp02', 'V0.82', '常用语设置,外接推送OA待办标题名称调整', 'released', '2026-05-25', '2026-06-24', '2026-06-24 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv04', 'SXk01', 'Xkp02', 'V0.9', '外接流程下拉选项调整,外接测试报告自动化生成,子账户台账调整,是否签署承诺函下拉框修改,审批结束后关闭待办,系统是否有界面下拉框修改,软件台账编辑功能，上传附件限制修改至100M,软件台账新增是否有界面字段,尽职调查字段下新增注释,外接子账户台账显示创建时间,外接流程新增模式下根据appid计算子账户系统核实字段', 'released', '2026-05-30', '2026-06-29', '2026-06-29 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv05', 'SXk01', 'Xkp02', 'V0.9.1', '软件台账新增是否有界面字段,外接流程解绑 appId修改为下拉选择,催办,流程终止发送消息给发起人-企微,外接合规报告生成渲染文本调整,外接流程管理菜单新增部分筛选字段,子账户台账模块重构', 'released', '2026-06-08', '2026-07-08', '2026-07-08 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv06', 'SXk01', 'Xkp02', 'V0.9.2', '子账户黑名单,外接生产授权码出来后，推送企微消息给发起人,外接流程界面查询优化,外接台账新增字段测试反馈表(Word/Excel),提供根据客户号查询是否存在有在途和生效的外接信息,分户管理资产交易编码对应名称 获取,客户实时数据同步,外接标题优化,销户流程对接,直链接模式和中继模式对于技术架构绑定关系,客户是自然人，且选择的外部接入标识为子账户，则不允许发起外接流程', 'released', '2026-06-15', '2026-07-15', '2026-07-15 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv07', 'SXk01', 'Xkp02', 'V0.9.3', '外接台账新增字段测试反馈表(Word/Excel),推送移动端消息链接URL为PC端链接，打开页面不正确,退回修改界面的上传的附件，在审批记录中不展示,分户管理资产交易编码对应名称 获取,客户实时数据同步,外接合规报告优化', 'released', '2026-06-23', '2026-07-23', '2026-07-23 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv08', 'SXk01', 'Xkp02', 'V0.9.4', '流程通用优化,程序化待办列宽自定义,暂存列表实现,主机托管台账单独签出,子账户台账自动写入；暂存、主机托管台账、复制、流程节点描述，子账户写入、提示调整', 'released', '2026-06-29', '2026-07-29', '2026-07-29 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv09', 'SXk01', 'Xkp02', 'V0.9.5', '新增待办页面供业务中台iframe嵌入查看,交还报表,手机端审批页面未正常关闭,子账户签报合并调整，避免多次审批,平台切换对接外接流程获取APPID,流程引擎退回BUG,外接-流程复制-已有模式下-部分字段改为台账覆盖,外接摘要固定优化', 'released', '2026-07-20', '2026-08-19', '2026-08-19 18:00:00', '2026-06-01 09:00:00', '2026-11-09 10:00:00'),
  ('Xkv10', 'SXk01', 'Xkp02', 'V1.2.0', '外接与主机托管的下一批需求，规划中。', 'planned', '2026-09-01', '2026-11-30', NULL, '2026-06-01 09:00:00', '2026-11-09 10:00:00');
