INSERT INTO requirement_doc_history (id, doc_id, workspace_id, version_no, title, content, format, saved_by, saved_by_user_id, created_at) VALUES
  ('Xkdh0000', 'Xkd0000', 'SXk01', 1, '主机托管历史数据迁移', '<p>将OA的主机托管台账迁移到本系统</p>', 'html', '施亚彬', 'Xku02', '2026-06-09 09:40:00'),
  ('Xkdh0001', 'Xkd0000', 'SXk01', 2, '主机托管历史数据迁移', '<p>将OA的主机托管台账迁移到本系统</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0002', 'Xkd0001', 'SXk01', 1, '主机托管流程', '<p>从OA流程迁移主机托管流程，实现主机托管流程的流转等</p>', 'html', '施亚彬', 'Xku02', '2026-06-09 09:40:00'),
  ('Xkdh0003', 'Xkd0001', 'SXk01', 2, '主机托管流程', '<p>从OA流程迁移主机托管流程，实现主机托管流程的流转等</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0004', 'Xkd0002', 'SXk01', 1, '主机托管表单', '<p>从OA流程迁移主机托管流程，实现主机托管表单逻辑的联动等</p>', 'html', '施亚彬', 'Xku02', '2026-06-09 09:40:00'),
  ('Xkdh0005', 'Xkd0002', 'SXk01', 2, '主机托管表单', '<p>从OA流程迁移主机托管流程，实现主机托管表单逻辑的联动等</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0006', 'Xkd0003', 'SXk01', 1, '外接台账写入', '<p>1、在中台底表（台账表：t_biz_software_ledger）中加这个字段，然后文件落地表。为了后期检查。 2、如果选已有，之前没有上传过子账户说明文件的，在审批意见——发起人中需要上传子账户功能证明材料（必填） 3、流程到一个组（组中人审批这个说明文件，或签，包含界面和非界面审批人） 4、已有授权这个流程走完，回写到台账表中，子账户功能证明材料和子账户材料确认</p>', 'html', '施亚彬', 'Xku02', '2026-06-08 09:40:00'),
  ('Xkdh0007', 'Xkd0003', 'SXk01', 2, '外接台账写入', '<p>1、在中台底表（台账表：t_biz_software_ledger）中加这个字段，然后文件落地表。为了后期检查。 2、如果选已有，之前没有上传过子账户说明文件的，在审批意见——发起人中需要上传子账户功能证明材料（必填） 3、流程到一个组（组中人审批这个说明文件，或签，包含界面和非界面审批人） 4、已有授权这个流程走完，回写到台账表中，子账户功能证明材料和子账户材料确认</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0008', 'Xkd0004', 'SXk01', 1, '企微消息推送', '<p>外接流程，新增授权码当中台程序化报备信息录入（即程序化信息写入监听器）后，触发企微消息给发起人</p>', 'html', '施亚彬', 'Xku02', '2026-06-08 09:40:00'),
  ('Xkdh0009', 'Xkd0004', 'SXk01', 2, '企微消息推送', '<p>外接流程，新增授权码当中台程序化报备信息录入（即程序化信息写入监听器）后，触发企微消息给发起人</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0010', 'Xkd0005', 'SXk01', 1, '外接台账查看', '<p>外接台账新增筛选便于业务人员使用</p>', 'html', '施亚彬', 'Xku02', '2026-06-08 09:40:00'),
  ('Xkdh0011', 'Xkd0005', 'SXk01', 2, '外接台账查看', '<p>外接台账新增筛选便于业务人员使用</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0012', 'Xkd0006', 'SXk01', 1, '对于审批人发起附言是否有常用语功能', '<p>对于审批人发起附言是否有常用语功能</p>', 'html', '施亚彬', 'Xku02', '2026-06-10 09:40:00'),
  ('Xkdh0013', 'Xkd0006', 'SXk01', 2, '对于审批人发起附言是否有常用语功能', '<p>对于审批人发起附言是否有常用语功能</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0014', 'Xkd0007', 'SXk01', 1, '流程功能节点处理时长展示', '<p>对于流程中处理卡点，做个统计。知道流程时间长是卡在哪里，怎么做优化</p>', 'html', '张伟', 'Xku01', '2026-06-10 09:40:00'),
  ('Xkdh0015', 'Xkd0008', 'SXk01', 1, '消户时提示他需要把外接解除绑定', '<p>客户号消户，需要对于这个客户号走过的外接发起解除绑定</p>', 'html', '施亚彬', 'Xku02', '2026-06-12 09:40:00'),
  ('Xkdh0016', 'Xkd0008', 'SXk01', 2, '消户时提示他需要把外接解除绑定', '<p>客户号消户，需要对于这个客户号走过的外接发起解除绑定</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0017', 'Xkd0009', 'SXk01', 1, '外接和程序化报备做到穿透', '<p>在外接中走到程序化报备用流程，做个穿透，可以在个流程中知道报备走到哪里了</p>', 'html', '张伟', 'Xku01', '2026-06-12 09:40:00'),
  ('Xkdh0018', 'Xkd0009', 'SXk01', 2, '外接和程序化报备做到穿透', '<p>在外接中走到程序化报备用流程，做个穿透，可以在个流程中知道报备走到哪里了</p>', 'html', '张伟', 'Xku01', '2026-08-19 18:00:00'),
  ('Xkdh0019', 'Xkd0010', 'SXk01', 1, '资金通资金信息查询', '<p>资金通资金信息查询</p>', 'html', '张亮', 'Xku04', '2026-06-15 09:40:00'),
  ('Xkdh0020', 'Xkd0010', 'SXk01', 2, '资金通资金信息查询', '<p>资金通资金信息查询</p>', 'html', '张亮', 'Xku04', '2026-08-19 18:00:00'),
  ('Xkdh0021', 'Xkd0011', 'SXk01', 1, '业务中台的主界面显示外接程序化代办', '<p>在业务中台的主界面中显示后期流程引擎的代办</p>', 'html', '张伟', 'Xku01', '2026-06-16 09:40:00'),
  ('Xkdh0022', 'Xkd0011', 'SXk01', 2, '业务中台的主界面显示外接程序化代办', '<p>在业务中台的主界面中显示后期流程引擎的代办</p>', 'html', '张伟', 'Xku01', '2026-08-19 18:00:00'),
  ('Xkdh0023', 'Xkd0012', 'SXk01', 1, '流程中被回退的在代办中特殊显示', '<p>流程中被回退的在代办中特殊显示，于正常代办流程有所区别，可以高亮或标识来区别</p>', 'html', '施亚彬', 'Xku02', '2026-06-16 09:40:00'),
  ('Xkdh0024', 'Xkd0012', 'SXk01', 2, '流程中被回退的在代办中特殊显示', '<p>流程中被回退的在代办中特殊显示，于正常代办流程有所区别，可以高亮或标识来区别</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0025', 'Xkd0013', 'SXk01', 1, '业务办理销户时提示未解除流程', '<p>业务办理销户时提示未解除流程，比如未外接解绑或托管流程未注销等</p>', 'html', '施亚彬', 'Xku02', '2026-06-16 09:40:00'),
  ('Xkdh0026', 'Xkd0013', 'SXk01', 2, '业务办理销户时提示未解除流程', '<p>业务办理销户时提示未解除流程，比如未外接解绑或托管流程未注销等</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0027', 'Xkd0014', 'SXk01', 1, '外接测试报告自动化生成功能', '<p>概要：通过外接流程的字段和外接审核人填写的字段，自动化生成word版外接测试报告。 1）报告的表头，程序名，版本号，appid，连接模式，柜台名称，测试审核人，预审人，当天日期均可以从流程中获取。 2）测试时间，测试账号，12个测试结果勾选，默认值参考报告模板。 3）柜台明细信息，与柜台名称绑定。 4）测试结论勾选，根据流程的“是否允许外接不允许程序化”的值，如果是允许外接允许程序化，则勾选通过；如果允许外接不允许程序化，则勾选不建议；如果不允许外接不允许程序化，则勾选不通过。 4）支持在测试审核节点多次生成，保留最新一次结果。</p>', 'html', '施亚彬', 'Xku02', '2026-06-16 09:40:00'),
  ('Xkdh0028', 'Xkd0014', 'SXk01', 2, '外接测试报告自动化生成功能', '<p>概要：通过外接流程的字段和外接审核人填写的字段，自动化生成word版外接测试报告。 1）报告的表头，程序名，版本号，appid，连接模式，柜台名称，测试审核人，预审人，当天日期均可以从流程中获取。 2）测试时间，测试账号，12个测试结果勾选，默认值参考报告模板。 3）柜台明细信息，与柜台名称绑定。 4）测试结论勾选，根据流程的“是否允许外接不允许程序化”的值，如果是允许外接允许程序化，则勾选通过；如果允许外接不允许程序化，则勾选不建议；如果不允许外接不允许程序化，则勾选不通过。 4）支持在测试审核节点多次生成，保留最新一次结果。</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
