  ('Xkdh0033', 'Xkd0017', 'SXk01', 1, '次席资金监控', '<p>落地资金通系统，实现全次席柜台全时段资金监控、自动预警通知，补齐原有系 统能力短板</p>', 'html', '张亮', 'Xku04', '2026-06-22 09:40:00'),
