  ('Xkdh0110', 'Xkd0056', 'SXk01', 2, '外接台账查询界面优化', '<p>客户号、流程编号对应的输入框和其他宽度保持一致</p>', 'html', '张伟', 'Xku01', '2026-08-19 18:00:00'),
