  ('Xkdh0115', 'Xkd0059', 'SXk01', 1, '中继模式新增上传资料', '<p>中继模式接入两种模式需要再上传用户事件截图作为通过的证明材料</p>', 'html', '施亚彬', 'Xku02', '2026-07-08 09:40:00'),
