  ('Xkdh0188', 'Xkd0102', 'SXk01', 2, '外接页面字段值维护的功能支持运维申请权限', '<p>外接页面字段值维护的功能支持运维申请权限</p>', 'html', '张伟', 'Xku01', '2026-08-19 18:00:00'),
  ('Xkdh0189', 'Xkd0103', 'SXk01', 1, '外接页面字段必传限制', '<p>运营研发部门知识库1、是否具有分子账户功能，上传附件说明增加内容【上传“申请使用子账户系统相关材料”】2、需求截图中的字段在提交时校验必填，且增加必填标识</p>', 'html', '张伟', 'Xku01', '2026-08-13 09:40:00'),
  ('Xkdh0190', 'Xkd0103', 'SXk01', 2, '外接页面字段必传限制', '<p>运营研发部门知识库1、是否具有分子账户功能，上传附件说明增加内容【上传“申请使用子账户系统相关材料”】2、需求截图中的字段在提交时校验必填，且增加必填标识</p>', 'html', '张伟', 'Xku01', '2026-08-19 18:00:00'),
  ('Xkdh0191', 'Xkd0104', 'SXk01', 1, '审批人已查看必审材料功能', '<p>审批人已查看必审材料功能</p>', 'html', '张伟', 'Xku01', '2026-08-13 09:40:00'),
  ('Xkdh0192', 'Xkd0105', 'SXk01', 1, '期货交易细则管理', '<p>运营研发部门知识库</p>', 'html', '程洪昌', 'Xku05', '2026-08-14 09:40:00'),
  ('Xkdh0193', 'Xkd0106', 'SXk01', 1, '主机托管首版上线前优化', '<p>运营研发部门知识库</p>', 'html', '施亚彬', 'Xku02', '2026-08-17 09:40:00'),
  ('Xkdh0194', 'Xkd0106', 'SXk01', 2, '主机托管首版上线前优化', '<p>运营研发部门知识库</p>', 'html', '施亚彬', 'Xku02', '2026-08-19 18:00:00'),
  ('Xkdh0195', 'Xkd0107', 'SXk01', 1, '外接等流程移动端审批优化', '<p>或签情况下，承办人员要先点承办再审批，现状是点击承办后先退出详情页再点进详情进行审批，需求为：点击承办后页面详情页刷新展示出审批的几个按钮，直接审批，审批后才推出详情回到待办列表页</p>', 'html', '张伟', 'Xku01', '2026-08-24 09:40:00'),
  ('Xkdh0196', 'Xkd0107', 'SXk01', 2, '外接等流程移动端审批优化', '<p>或签情况下，承办人员要先点承办再审批，现状是点击承办后先退出详情页再点进详情进行审批，需求为：点击承办后页面详情页刷新展示出审批的几个按钮，直接审批，审批后才推出详情回到待办列表页</p>', 'html', '张伟', 'Xku01', '2026-08-24 18:00:00'),
  ('Xkdh0197', 'Xkd0108', 'SXk01', 1, '接口自动化测试', '<p>接口自动化测试</p>', 'html', '施亚彬', 'Xku02', '2026-08-25 09:40:00'),
  ('Xkdh0198', 'Xkd0109', 'SXk01', 1, '自研流程菜单角色权限配置调整', '<p>运营研发部门知识库菜单的角色授权，目前支持粒度是”程序化交易“，但程序化交易下还有”信息系统外部接入审批、外部系统系统解绑审批、外部系统退出审批“以及即将上线的”主机托管“，其中”外部系统退出审批“是无需对前线业务开放的，故提此需求： 支持菜单的角色授权到最小菜单粒度</p>', 'html', '张伟', 'Xku01', '2026-08-25 09:40:00'),
  ('Xkdh0199', 'Xkd0109', 'SXk01', 2, '自研流程菜单角色权限配置调整', '<p>运营研发部门知识库菜单的角色授权，目前支持粒度是”程序化交易“，但程序化交易下还有”信息系统外部接入审批、外部系统系统解绑审批、外部系统退出审批“以及即将上线的”主机托管“，其中”外部系统退出审批“是无需对前线业务开放的，故提此需求： 支持菜单的角色授权到最小菜单粒度</p>', 'html', '张伟', 'Xku01', '2026-08-25 18:00:00');
INSERT INTO requirement_doc_history (id, doc_id, workspace_id, version_no, title, content, format, saved_by, saved_by_user_id, created_at) VALUES
  ('Xkdh0200', 'Xkd0110', 'SXk01', 1, '切平台流程和外接流程柜台信息保持一致', '<p>提供平台系统维护的字典信息至供应商，支持供应商根据平台信息+客户号查询APPID</p>', 'html', '张伟', 'Xku01', '2026-08-25 09:40:00'),
  ('Xkdh0201', 'Xkd0111', 'SXk01', 1, '（待王越峰明确需求）外接发起人与尽调人员不一致需尽调人员确认', '<p>运营研发部门知识库  发起人提交申请后，系统通过OA向尽调人员发送待办；尽调人员完成承诺确认；发起人再次提交时校验尽调人员是否已完成承诺，若已完成流程继续。</p>', 'html', '张伟', 'Xku01', '2026-08-25 09:40:00'),
  ('Xkdh0202', 'Xkd0112', 'SXk01', 1, '外接客户白名单管理', '<p>运营研发部门知识库 1、现有白名单功能扩展，支持对同一个客户维护不同的外接白名单类型（简化子账户尽调材料、免软件尽调、不使用子账户功能免过高管）</p>', 'html', '张伟', 'Xku01', '2026-08-28 09:40:00'),
  ('Xkdh0203', 'Xkd0113', 'SXk01', 1, '外接系统标识格式校验', '<p>外接系统标识格式按照“厂商名_软件名_版本号（厂商名≤10位，软件名≤10位，版本号≤8位，总长≤30位）”的格式进行校验，下划线只能有2个，各段字符长度不能超</p>', 'html', '张伟', 'Xku01', '2026-08-28 09:40:00'),
  ('Xkdh0204', 'Xkd0113', 'SXk01', 2, '外接系统标识格式校验', '<p>外接系统标识格式按照“厂商名_软件名_版本号（厂商名≤10位，软件名≤10位，版本号≤8位，总长≤30位）”的格式进行校验，下划线只能有2个，各段字符长度不能超</p>', 'html', '张伟', 'Xku01', '2026-08-28 18:00:00'),
  ('Xkdh0205', 'Xkd0114', 'SXk01', 1, '会服通知-上期能源套保超仓预警通知', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-08-28 09:40:00'),
  ('Xkdh0206', 'Xkd0115', 'SXk01', 1, '掌厅业务未通过等3类通知', '<p>运营研发部门知识库</p>', 'html', '肖威', 'Xku08', '2026-09-01 09:40:00'),
  ('Xkdh0207', 'Xkd0116', 'SXk01', 1, '外接“已有”流程申请去掉第二次经过发起人的节点', '<p>外接-已有授权码流程，原来是发起人，二级部门负责人，再发起人（填写客户号），调整为发起人第一次必填客户号，后面第二次到发起人的节点去掉</p>', 'html', '张伟', 'Xku01', '2026-09-02 09:40:00'),
  ('Xkdh0208', 'Xkd0116', 'SXk01', 2, '外接“已有”流程申请去掉第二次经过发起人的节点', '<p>外接-已有授权码流程，原来是发起人，二级部门负责人，再发起人（填写客户号），调整为发起人第一次必填客户号，后面第二次到发起人的节点去掉</p>', 'html', '张伟', 'Xku01', '2026-09-02 18:00:00'),
  ('Xkdh0209', 'Xkd0117', 'SXk01', 1, '主机托管台账支持新增、编辑及增加字段', '<p>1、主机托管台帐增加“新增”功能，补救因流程有、但没有落底表的情况（主要针对OA流程没有落底表的场景） 2、主机托管客户台帐的“编辑”功能，编辑弹窗中的所有字段均支持修改（现在有6个字段不支持编辑，服务器序列号可能在返厂维修后会变）补完主机后也需要补客户信息 3、主机托客台帐上的编辑和新增页面需要把其他业务字段展示出来，并且支持可以编辑对应字段的枚举值</p>', 'html', '施亚彬', 'Xku02', '2026-09-03 09:40:00'),
  ('Xkdh0210', 'Xkd0117', 'SXk01', 2, '主机托管台账支持新增、编辑及增加字段', '<p>1、主机托管台帐增加“新增”功能，补救因流程有、但没有落底表的情况（主要针对OA流程没有落底表的场景） 2、主机托管客户台帐的“编辑”功能，编辑弹窗中的所有字段均支持修改（现在有6个字段不支持编辑，服务器序列号可能在返厂维修后会变）补完主机后也需要补客户信息 3、主机托客台帐上的编辑和新增页面需要把其他业务字段展示出来，并且支持可以编辑对应字段的枚举值</p>', 'html', '施亚彬', 'Xku02', '2026-09-03 18:00:00'),
  ('Xkdh0211', 'Xkd0118', 'SXk01', 1, '抄送改造-支持角色维度抄送', '<p>现在的抄送只支持抄送到人，需支持指定角色抄送</p>', 'html', '张亮', 'Xku04', '2026-09-03 09:40:00'),
  ('Xkdh0212', 'Xkd0119', 'SXk01', 1, '会服通知-上期能源套利超仓预警通知', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0213', 'Xkd0120', 'SXk01', 1, '会服通知-大商所套保交割月预计超仓预警', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0214', 'Xkd0121', 'SXk01', 1, '会服通知-上期能源客户非套保超仓预警', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0215', 'Xkd0122', 'SXk01', 1, '会服通知-上期能源账户组合并超仓预警', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0216', 'Xkd0123', 'SXk01', 1, '会服通知-郑商所下阶段超仓提醒', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0217', 'Xkd0124', 'SXk01', 1, '会服通知-上期能源实控组超仓通知', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-22 09:40:00'),
  ('Xkdh0218', 'Xkd0125', 'SXk01', 1, '发起人或审批人离职的在途流程处理', '<p>做一个查询功能，支持运维根据用户查询其涉及的流程（包括发起和审批）、同时针对该用户涉及的流程支持运维进行终止操作</p>', 'html', '张伟', 'Xku01', '2026-09-03 09:40:00'),
  ('Xkdh0219', 'Xkd0126', 'SXk01', 1, '外接面单页面字段隐藏、调整名称及编辑权限调整', '<p>1、&quot;开发人/企业名称&quot; 改名 &quot;开发和维护主体&quot;； 2、去掉【 尽职调查】第4个字段“系统功能说明材料“对应的标准 / 非标准下拉框，默认必传附件； 3、去掉【系统部署情况】部分”软件维护主体、维护人/企业名称、运维模式“；去掉【软件基本信息】部分的”系统用途“； 4、【尽职调查】第7个字段第二次到发起人时允许编辑。</p>', 'html', '张伟', 'Xku01', '2026-09-03 09:40:00'),
  ('Xkdh0220', 'Xkd0126', 'SXk01', 2, '外接面单页面字段隐藏、调整名称及编辑权限调整', '<p>1、&quot;开发人/企业名称&quot; 改名 &quot;开发和维护主体&quot;； 2、去掉【 尽职调查】第4个字段“系统功能说明材料“对应的标准 / 非标准下拉框，默认必传附件； 3、去掉【系统部署情况】部分”软件维护主体、维护人/企业名称、运维模式“；去掉【软件基本信息】部分的”系统用途“； 4、【尽职调查】第7个字段第二次到发起人时允许编辑。</p>', 'html', '张伟', 'Xku01', '2026-09-03 18:00:00'),
  ('Xkdh0221', 'Xkd0127', 'SXk01', 1, '外接原承诺话术调整及新增二级部门负责人承诺确认', '<p>运营研发部门知识库 1、原承诺话术调整 2、二级部门负责人节点增加尽调合适确认承诺</p>', 'html', '张伟', 'Xku01', '2026-09-09 09:40:00'),
  ('Xkdh0222', 'Xkd0128', 'SXk01', 1, '实体机资产维护与流程集成', '<p>运营研发部门知识库1、支持用户维护：实体机类型、序列号、固定资产编号、机器所在位置、是否空闲 2、在申请的表单页面展示出可借用服务器数量 3、周顺填写借用实体机服务器序列号时可以下拉选</p>', 'html', '施亚彬', 'Xku02', '2026-09-11 09:40:00'),
  ('Xkdh0223', 'Xkd0128', 'SXk01', 2, '实体机资产维护与流程集成', '<p>运营研发部门知识库1、支持用户维护：实体机类型、序列号、固定资产编号、机器所在位置、是否空闲 2、在申请的表单页面展示出可借用服务器数量 3、周顺填写借用实体机服务器序列号时可以下拉选</p>', 'html', '施亚彬', 'Xku02', '2026-09-11 18:00:00'),
  ('Xkdh0224', 'Xkd0129', 'SXk01', 1, '业务字典维护', '<p>仅可修改业务相关枚举值</p>', 'html', '张伟', 'Xku01', '2026-09-11 09:40:00'),
  ('Xkdh0225', 'Xkd0129', 'SXk01', 2, '业务字典维护', '<p>仅可修改业务相关枚举值</p>', 'html', '张伟', 'Xku01', '2026-09-11 18:00:00'),
  ('Xkdh0226', 'Xkd0130', 'SXk01', 1, '主机托管非借用公司资产无需填写服务器和实体机类型', '<p>当托管流程发起人，先非借用时，不需要展示服务器类型和实体机类型</p>', 'html', '施亚彬', 'Xku02', '2026-09-11 09:40:00'),
  ('Xkdh0227', 'Xkd0131', 'SXk01', 1, '常用语字体颜色调整优化', '<p>现在提示语为红色，和报错信息颜色一致，视觉不统一，进行修改</p>', 'html', '施亚彬', 'Xku02', '2026-09-15 09:40:00'),
  ('Xkdh0228', 'Xkd0131', 'SXk01', 2, '常用语字体颜色调整优化', '<p>现在提示语为红色，和报错信息颜色一致，视觉不统一，进行修改</p>', 'html', '施亚彬', 'Xku02', '2026-09-15 18:00:00'),
  ('Xkdh0229', 'Xkd0132', 'SXk01', 1, '外接台账管理软件信息台账和客户信息台账支持新增', '<p>在中台台帐管理中，外接软件信息台帐和客户信息台帐中添加手动添加台帐功能，支持业务补充OA流程疏落的台账信息，新增的页面同现有编辑弹窗页</p>', 'html', '张伟', 'Xku01', '2026-09-16 09:40:00'),
  ('Xkdh0230', 'Xkd0132', 'SXk01', 2, '外接台账管理软件信息台账和客户信息台账支持新增', '<p>在中台台帐管理中，外接软件信息台帐和客户信息台帐中添加手动添加台帐功能，支持业务补充OA流程疏落的台账信息，新增的页面同现有编辑弹窗页</p>', 'html', '张伟', 'Xku01', '2026-09-16 18:00:00'),
  ('Xkdh0231', 'Xkd0133', 'SXk01', 1, '子账户黑名单名称调整为外接软件黑名单', '<p>外接软件黑名单不能走外部接入申请流程，现在tab名称是子账户黑名单，实际不管软件是不是子账户都不能接，所以名称应调整为外接软件黑名单</p>', 'html', '张伟', 'Xku01', '2026-09-16 09:40:00'),
  ('Xkdh0232', 'Xkd0133', 'SXk01', 2, '子账户黑名单名称调整为外接软件黑名单', '<p>外接软件黑名单不能走外部接入申请流程，现在tab名称是子账户黑名单，实际不管软件是不是子账户都不能接，所以名称应调整为外接软件黑名单</p>', 'html', '张伟', 'Xku01', '2026-09-16 18:00:00'),
  ('Xkdh0233', 'Xkd0134', 'SXk01', 1, '主机托管迁移和注销流程调整', '<p>1、迁移流程如果新机房是核心机房，需要发起后过交易部对核心机房材料做审核，因没有客户签字材料不需要客服部审核了。交易部节点增加在一级部门负责人和王越峰之间 2、是否关闭网络端口判断及网络处理人员移到新机房处理之后，周顺处理之前 3、注销流程在崔吉节点前增加判断，是否关闭网络端口，是  经过崔吉，否 不需要过崔吉</p>', 'html', '张伟', 'Xku01', '2026-09-16 09:40:00'),
  ('Xkdh0234', 'Xkd0134', 'SXk01', 2, '主机托管迁移和注销流程调整', '<p>1、迁移流程如果新机房是核心机房，需要发起后过交易部对核心机房材料做审核，因没有客户签字材料不需要客服部审核了。交易部节点增加在一级部门负责人和王越峰之间 2、是否关闭网络端口判断及网络处理人员移到新机房处理之后，周顺处理之前 3、注销流程在崔吉节点前增加判断，是否关闭网络端口，是  经过崔吉，否 不需要过崔吉</p>', 'html', '张伟', 'Xku01', '2026-09-16 18:00:00'),
  ('Xkdh0235', 'Xkd0135', 'SXk01', 1, '主机托管后台业务流程查询增加快递单号的筛选项', '<p>业务流程查询（后台）→主机托管申请，筛选项中增加“快递单号”字段，字段后的控件为文本输入框，默认提示“请输入快递单号”，支持模糊查询</p>', 'html', '施亚彬', 'Xku02', '2026-09-16 09:40:00'),
  ('Xkdh0236', 'Xkd0135', 'SXk01', 2, '主机托管后台业务流程查询增加快递单号的筛选项', '<p>业务流程查询（后台）→主机托管申请，筛选项中增加“快递单号”字段，字段后的控件为文本输入框，默认提示“请输入快递单号”，支持模糊查询</p>', 'html', '施亚彬', 'Xku02', '2026-09-16 18:00:00'),
  ('Xkdh0237', 'Xkd0136', 'SXk01', 1, '主机托管托管机器品牌配置', '<p>运营研发部门知识库1、「托管机器类型」枚举值增加”其他“ 2、「服务器类型」「实体机/虚拟机类型」两个字段仅当托管机器类型=服务器时显示；托管机器类型为路由器/交换机/其他时不展示 3、「托管服务器品牌」和「托管服务器型号」字段名调整为「托管机器品牌」「托管机器型号」 4、在主机托管配置菜单页面增加配置功能【机器品牌配置】，支持增删改查，字段：序号、托管机器类型、品牌、状态、备注、更新人/更新时间、操作 5、配置后申请表单页面的托管机器品牌改为二级下拉选</p>', 'html', '施亚彬', 'Xku02', '2026-09-17 09:40:00'),
  ('Xkdh0238', 'Xkd0136', 'SXk01', 2, '主机托管托管机器品牌配置', '<p>运营研发部门知识库1、「托管机器类型」枚举值增加”其他“ 2、「服务器类型」「实体机/虚拟机类型」两个字段仅当托管机器类型=服务器时显示；托管机器类型为路由器/交换机/其他时不展示 3、「托管服务器品牌」和「托管服务器型号」字段名调整为「托管机器品牌」「托管机器型号」 4、在主机托管配置菜单页面增加配置功能【机器品牌配置】，支持增删改查，字段：序号、托管机器类型、品牌、状态、备注、更新人/更新时间、操作 5、配置后申请表单页面的托管机器品牌改为二级下拉选</p>', 'html', '施亚彬', 'Xku02', '2026-09-17 18:00:00'),
  ('Xkdh0239', 'Xkd0137', 'SXk01', 1, '程序化待办列表支持自动刷新', '<p>程序化待办列表支持自动刷新</p>', 'html', '张伟', 'Xku01', '2026-09-17 09:40:00'),
  ('Xkdh0240', 'Xkd0138', 'SXk01', 1, '流程审批中的退回操作功能拆分', '<p>运营研发部门知识库原有【退回】配置项替换为 4 个独立配置项，流程管理人可按节点配置允许的退回操作</p>', 'html', '张伟', 'Xku01', '2026-09-17 09:40:00'),
  ('Xkdh0241', 'Xkd0139', 'SXk01', 1, '主机托管签字材料置顶放置', '<p>将需要客户签字的文件在申请表单页置顶放置，支持用户下载（参考外接流程）</p>', 'html', '张伟', 'Xku01', '2026-09-17 09:40:00'),
  ('Xkdh0242', 'Xkd0139', 'SXk01', 2, '主机托管签字材料置顶放置', '<p>将需要客户签字的文件在申请表单页置顶放置，支持用户下载（参考外接流程）</p>', 'html', '张伟', 'Xku01', '2026-09-17 18:00:00'),
  ('Xkdh0243', 'Xkd0140', 'SXk01', 1, '审批流程中连着过两次同一审批人的合并为一次', '<p>背景：现在外接流程中有的一级部门负责人授权给某个二级部门负责人审批，导致流程会连续两次过二级部门负责人，相当于该用户收到一条待办批了，再收到一条待办再批一次 需求：连续两次过这个某个实际审批人的，批一次同意，两个节点直接审批通过</p>', 'html', '张伟', 'Xku01', '2026-09-17 09:40:00'),
  ('Xkdh0244', 'Xkd0141', 'SXk01', 1, '主机托管流程增加”是否借用网卡“判断', '<p>1、先加工是否借用网卡的条件字段 2、在流程设计中”第一次判断是否借用“以及其后”服务器类型=实体机“两处增加”是否借用网卡=是“的判断条件 3、该分支走到周顺节点时，需增加开放”网卡序列号“字段可编辑</p>', 'html', '张伟', 'Xku01', '2026-09-18 09:40:00'),
  ('Xkdh0245', 'Xkd0141', 'SXk01', 2, '主机托管流程增加”是否借用网卡“判断', '<p>1、先加工是否借用网卡的条件字段 2、在流程设计中”第一次判断是否借用“以及其后”服务器类型=实体机“两处增加”是否借用网卡=是“的判断条件 3、该分支走到周顺节点时，需增加开放”网卡序列号“字段可编辑</p>', 'html', '张伟', 'Xku01', '2026-09-18 18:00:00'),
  ('Xkdh0246', 'Xkd0142', 'SXk01', 1, '迁移流程不关闭网络复制IP和电量字段值到新机房对应字段中', '<p>托管流程机房迁移老机房管理员会选是否关闭网络，如果选不关闭，把老机房的ip地址信息带到新机房的ip地址位置，电量字段也带到新机房的电量字段中，新机房可编辑，编辑后台账正常更新</p>', 'html', '施亚彬', 'Xku02', '2026-09-21 09:40:00'),
  ('Xkdh0247', 'Xkd0142', 'SXk01', 2, '迁移流程不关闭网络复制IP和电量字段值到新机房对应字段中', '<p>托管流程机房迁移老机房管理员会选是否关闭网络，如果选不关闭，把老机房的ip地址信息带到新机房的ip地址位置，电量字段也带到新机房的电量字段中，新机房可编辑，编辑后台账正常更新</p>', 'html', '施亚彬', 'Xku02', '2026-09-21 18:00:00'),
  ('Xkdh0248', 'Xkd0143', 'SXk01', 1, '主机托管发起时校验“操作系统版本号”必填', '<p>主机托管发起时校验“操作系统版本号”必填</p>', 'html', '施亚彬', 'Xku02', '2026-09-22 09:40:00'),
  ('Xkdh0249', 'Xkd0144', 'SXk01', 1, '外接黑名单在可选择的appid中不展示', '<p>外接黑名单在已有授权码场景下，业务选择【外接系统标识】对应的弹窗列表中中不展示</p>', 'html', '施亚彬', 'Xku02', '2026-09-22 09:40:00'),
  ('Xkdh0250', 'Xkd0145', 'SXk01', 1, '外接流程中客户部签字审核节点调整至交易管理部和王越峰之间', '<p>外接流程中客户部签字审核节点调整至交易管理部和王越峰之间</p>', 'html', '施亚彬', 'Xku02', '2026-09-23 09:40:00'),
  ('Xkdh0251', 'Xkd0145', 'SXk01', 2, '外接流程中客户部签字审核节点调整至交易管理部和王越峰之间', '<p>外接流程中客户部签字审核节点调整至交易管理部和王越峰之间</p>', 'html', '施亚彬', 'Xku02', '2026-09-23 18:00:00'),
  ('Xkdh0252', 'Xkd0146', 'SXk01', 1, '提供接口供销户流程查询客户主机托管的序列号', '<p>如果A机器上有5个客户，然后其中一个客户销户了，业务就无法发起主机托管的报备和迁移流程，故需在客户销户时判断客户是否有为解绑的托管机器，若有需要提醒业务先发起托管注销</p>', 'html', '张伟', 'Xku01', '2026-09-23 09:40:00'),
  ('Xkdh0253', 'Xkd0147', 'SXk01', 1, '程序化报备重构', '<p>程序化报备重构</p>', 'html', '施亚彬', 'Xku02', '2026-09-30 09:40:00'),
  ('Xkdh0254', 'Xkd0148', 'SXk01', 1, '使用子账户功能客户季度报告', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-23 09:40:00'),
  ('Xkdh0255', 'Xkd0149', 'SXk01', 1, '优化合规节点“加入子账户白名单”时机', '<p>优化合规节点“加入子账户白名单”时机</p>', 'html', '施亚彬', 'Xku02', '2026-10-08 09:40:00'),
  ('Xkdh0256', 'Xkd0150', 'SXk01', 1, '主机托管台账多客户或多序列号查询', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-10-08 09:40:00'),
  ('Xkdh0257', 'Xkd0151', 'SXk01', 1, '首页待办列表刷新逻辑优化', '<p>首页待办列表看到的托管流程，在程序化待办中处理之后再返回首页，条数没有变化</p>', 'html', '张伟', 'Xku01', '2026-10-09 09:40:00'),
  ('Xkdh0258', 'Xkd0152', 'SXk01', 1, '主机托管交换机或路由器关联操作系统等字段逻辑调整', '<p>原始需求：选了交换机或路由器，不需要填写操作系统、操作系统版本号、是否需要安装系统，这三个字段 变更为：托管机器类型只要不是“服务器”，就不展示  操作系统、操作系统版本号、是否需要安装系统   这3个字段</p>', 'html', '张伟', 'Xku01', '2026-10-12 09:40:00'),
  ('Xkdh0259', 'Xkd0153', 'SXk01', 1, '业务查询中的流程编号支持模糊查询', '<p>业务查询中的筛选条件【流程编号】支持模糊查询（前模糊后模糊都支持） 背景：业务遇到问题后发给技术截图，一般需要输入后几位数字进行查询，现在必须输完整的流程编号</p>', 'html', '张伟', 'Xku01', '2026-10-12 09:40:00'),
  ('Xkdh0260', 'Xkd0154', 'SXk01', 1, '外接台账写入节点调整', '<p>外接台账写入节点调整</p>', 'html', '施亚彬', 'Xku02', '2026-10-13 09:40:00'),
  ('Xkdh0261', 'Xkd0155', 'SXk01', 1, '外接校验程序化报备软件时过滤掉失效的软件', '<p>外接校验程序化报备信息时过滤掉失效的程序化报备软件</p>', 'html', '张伟', 'Xku01', '2026-10-12 09:40:00'),
  ('Xkdh0262', 'Xkd0155', 'SXk01', 2, '外接校验程序化报备软件时过滤掉失效的软件', '<p>外接校验程序化报备信息时过滤掉失效的程序化报备软件</p>', 'html', '张伟', 'Xku01', '2026-10-12 18:00:00'),
  ('Xkdh0263', 'Xkd0156', 'SXk01', 1, '在途流程支持运维设置委托代理人', '<p>由于业务人员离职导致目前在途的流程只能终止重发，期望可以支持运维能够针对在途流程中已注销账号的人员设置代理</p>', 'html', '施亚彬', 'Xku02', '2026-10-14 09:40:00'),
  ('Xkdh0264', 'Xkd0157', 'SXk01', 1, '注销账号存在在途流程定时通知运维', '<p>每天定时通知运维有哪些离职的人员还有在途流程未处理，便于运维针对性的设置委托代理</p>', 'html', '施亚彬', 'Xku02', '2026-10-14 09:40:00'),
  ('Xkdh0265', 'Xkd0158', 'SXk01', 1, '外接客户季度年度监测评估表', '<p>运营研发部门知识库</p>', 'html', '张伟', 'Xku01', '2026-09-23 09:40:00'),
  ('Xkdh0266', 'Xkd0159', 'SXk01', 1, '文件审核', '<p>对接文件审核系统，实现流程中的附件提交审核、审核结果回调、审核状态展示等功能</p>', 'html', '张伟', 'Xku01', '2026-10-19 09:40:00'),
  ('Xkdh0267', 'Xkd0160', 'SXk01', 1, '客户信息台账导出增加子账户相关字段', '<p>客户信息台账导出增加以下字段： 是否具有分、子账户功能 是否使用该功能、 使用该功能的具体原因、 子账户数量 子账户管理模式</p>', 'html', '程洪昌', 'Xku05', '2026-10-19 09:40:00'),
  ('Xkdh0268', 'Xkd0161', 'SXk01', 1, '主机托管台账历史业务负责人完善', '<p>主机托管台账历史业务负责人完善</p>', 'html', '施亚彬', 'Xku02', '2026-10-20 09:40:00'),
  ('Xkdh0269', 'Xkd0162', 'SXk01', 1, '外接客户信息台账增加客户一、二级部门的查询与筛选', '<p>在台账管理-客户信息台账中增加按客户一级部门、二级部门进行查询与筛选的功能，可参考SQL：ads_gop_investorproperty_all_a agiaa WHERE agiaa.fa_partyid = 02</p>', 'html', '张伟', 'Xku01', '2026-10-21 09:40:00'),
  ('Xkdh0270', 'Xkd0163', 'SXk01', 1, '外接客户底表增加解绑时间字段', '<p>记录解绑时间（先记录最近一次的解绑时间），确保合规使用子账户功能客户报告需求中扫描台账数据时不遗漏应进行报告的客户</p>', 'html', '张伟', 'Xku01', '2026-10-21 09:40:00'),
  ('Xkdh0271', 'Xkd0164', 'SXk01', 1, '主机托管实体机资产配置字段逻辑调整', '<p>1、固定资产编号改为非必填；2、增加一个品牌字段，文本输入框，非必填；3、实体机资产配置新增及编辑页面选择机房时，支持选到停用的机房</p>', 'html', '张伟', 'Xku01', '2026-10-23 09:40:00'),
  ('Xkdh0272', 'Xkd0164', 'SXk01', 2, '主机托管实体机资产配置字段逻辑调整', '<p>1、固定资产编号改为非必填；2、增加一个品牌字段，文本输入框，非必填；3、实体机资产配置新增及编辑页面选择机房时，支持选到停用的机房</p>', 'html', '张伟', 'Xku01', '2026-10-23 18:00:00'),
  ('Xkdh0273', 'Xkd0165', 'SXk01', 1, '报表平台附件内容为空是否发送加默认值', '<p>定时任务配置项“附件内容是否为空”设置默认值为空</p>', 'html', '张伟', 'Xku01', '2026-10-26 09:40:00'),
  ('Xkdh0274', 'Xkd0166', 'SXk01', 1, '主机托管是否借用公司资产字段名调整', '<p>流程中选择的是否借用公司资产实际上是技术部采购的，设备归属中选择的“公司资产”实际上是不同业务部门的资产；所以要把【是否借用公司资产】这个字段名改为【是否借用技术部资产】</p>', 'html', '张伟', 'Xku01', '2026-10-27 09:40:00'),
  ('Xkdh0275', 'Xkd0166', 'SXk01', 2, '主机托管是否借用公司资产字段名调整', '<p>流程中选择的是否借用公司资产实际上是技术部采购的，设备归属中选择的“公司资产”实际上是不同业务部门的资产；所以要把【是否借用公司资产】这个字段名改为【是否借用技术部资产】</p>', 'html', '张伟', 'Xku01', '2026-10-27 18:00:00'),
  ('Xkdh0276', 'Xkd0167', 'SXk01', 1, '页面UI统一', '<p>统一现在的页面风格（涉及的页面1、消息中心-消息中心配置、消息发送记录查询、批量任务管理；2、程序化中心-我的暂存、我的发起、已办任务；3、程序化台账-下所有二级菜单对应的所有tab页）： 1、查询条件和列表区域分开 2、搜索和重置按钮统一放在列表右侧 3、列显示项、新增、批量新增、导出按钮统一放在列表区域右上角 4、查询条件中各字段的名字右对齐，字段对应的输入框宽度保持一致 5、列表区的“隐藏搜索”和“刷新”两个小图标去掉 6、查询条件中的日期区间控件，使用element ui 的组件DatePicker（选择日期范围-默认）</p>', 'html', '张伟', 'Xku01', '2026-10-27 09:40:00'),
  ('Xkdh0277', 'Xkd0167', 'SXk01', 2, '页面UI统一', '<p>统一现在的页面风格（涉及的页面1、消息中心-消息中心配置、消息发送记录查询、批量任务管理；2、程序化中心-我的暂存、我的发起、已办任务；3、程序化台账-下所有二级菜单对应的所有tab页）： 1、查询条件和列表区域分开 2、搜索和重置按钮统一放在列表右侧 3、列显示项、新增、批量新增、导出按钮统一放在列表区域右上角 4、查询条件中各字段的名字右对齐，字段对应的输入框宽度保持一致 5、列表区的“隐藏搜索”和“刷新”两个小图标去掉 6、查询条件中的日期区间控件，使用element ui 的组件DatePicker（选择日期范围-默认）</p>', 'html', '张伟', 'Xku01', '2026-10-27 18:00:00'),
  ('Xkdh0278', 'Xkd0168', 'SXk01', 1, '期货与股票期权交易接口对接', '<p>对接期货和股票期权的交易接口，实现客户的资金等查询</p>', 'html', '肖威', 'Xku08', '2026-10-28 09:40:00'),
  ('Xkdh0279', 'Xkd0169', 'SXk01', 1, '智能审核在外接流程中展现规则调整', '<p>1、将原来直接在审核节点后显示的审核结果文字调整为图标 2、结果描述调整下（不要直接展示通过不通过） 3、打印的时候不要打印智能审核的结果</p>', 'html', '张伟', 'Xku01', '2026-10-30 09:40:00'),
  ('Xkdh0280', 'Xkd0169', 'SXk01', 2, '智能审核在外接流程中展现规则调整', '<p>1、将原来直接在审核节点后显示的审核结果文字调整为图标 2、结果描述调整下（不要直接展示通过不通过） 3、打印的时候不要打印智能审核的结果</p>', 'html', '张伟', 'Xku01', '2026-10-30 18:00:00'),
